INSERT INTO educational_content (grade,category,title,chapter,content,sort_order,active) VALUES
(12,'objectives','trueFalse · 11','8','{"section":"trueFalse","number":11,"text":"Interference of light waves is the modification in distribution of light energy (intensity).","answer":true}'::jsonb,11,true),
(12,'objectives','trueFalse · 12','8','{"section":"trueFalse","number":12,"text":"When light waves that are in phase interfere, minimum intensity of light is obtained.","answer":false}'::jsonb,12,true),
