(12,'objectives','trueFalse · 14','8','{"section":"trueFalse","number":14,"text":"The waves having same wavelength have single colour.","answer":true}'::jsonb,14,true),
(12,'objectives','trueFalse · 15','8','{"section":"trueFalse","number":15,"text":"If the waves that are in phase have same wavelength, they are coherent.","answer":true}'::jsonb,15,true),
