(12,'objectives','trueFalse · 17','8','{"section":"trueFalse","number":17,"text":"If the waves are monochromatic, they are also coherent.","answer":false}'::jsonb,17,true),
(12,'objectives','trueFalse · 18','8','{"section":"trueFalse","number":18,"text":"In double-slit experiment, the bright fringe at centre of screen is called central bright line.","answer":true}'::jsonb,18,true),
(12,'objectives','trueFalse · 19','8','{"section":"trueFalse","number":19,"text":"Bright and dark fringes are created by interference of light waves.","answer":true}'::jsonb,19,true),
(12,'objectives','trueFalse · 20','8','{"section":"trueFalse","number":20,"text":"In Young double-slit experiment, bright fringe appears at the centre of the screen.","answer":true}'::jsonb,20,true),
(12,'objectives','trueFalse · 21','8','{"section":"trueFalse","number":21,"text":"In double slit experiment, order of fringe, m = 0 for 1st order bright fringe.","answer":false}'::jsonb,21,true),
