(12,'objectives','trueFalse · 24','8','{"section":"trueFalse","number":24,"text":"If the aperture is much larger than the wavelength of light, the bending will be almost unnoticeable.","answer":true}'::jsonb,24,true),
(12,'objectives','trueFalse · 25','8','{"section":"trueFalse","number":25,"text":"If source of light and the screen are at finite distance from the obstacle, Fresnel diffraction will be occurred.","answer":true}'::jsonb,25,true),
